import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import express from 'express';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { verifyJwt } from '../server/lib/jwt.ts';
import { router } from '../server/routes.ts';

let server: Server;
let base: string;

beforeAll(async () => {
  const app = express();
  app.use(express.json());
  app.use('/api', router);
  await new Promise<void>((resolve) => {
    server = app.listen(0, () => resolve());
  });
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});

afterAll(() => new Promise<void>((resolve) => server.close(() => resolve())));

function login(email: string, password: string): Promise<Response> {
  return fetch(`${base}/api/login`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ email, password }),
  });
}

describe('POST /api/login', () => {
  it('returns a usable token for the right password', async () => {
    const response = await login('ada@example.com', 'correct horse battery staple');
    expect(response.status).toBe(200);

    const body = (await response.json()) as { token: string };
    expect(verifyJwt(body.token)).toMatchObject({ sub: 'u_1001', role: 'admin' });
  });

  it('rejects a wrong password without leaking a token', async () => {
    const response = await login('ada@example.com', 'not-the-password');
    expect(response.status).toBe(401);

    const body = (await response.json()) as { error?: string; token?: string };
    expect(body.error).toBe('Invalid email or password');
    expect(body.token).toBeUndefined();
  });
});
